import{c as s,Q as a,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const p="/assets/%E7%AE%97%E5%AD%90%E5%B7%A5%E7%A8%8B%E7%BC%96%E8%AF%91%E7%A4%BA%E6%84%8F%E5%9B%BE.BD6Sx5lL.png",d=JSON.parse('{"title":"算子工程编译","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子工程编译","slug":"算子工程编译"},{"level":2,"title":"编译步骤","slug":"编译步骤"},{"level":2,"title":"算子包交叉编译","slug":"算子包交叉编译"},{"level":2,"title":"支持自定义编译选项","slug":"支持自定义编译选项"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子工程编译.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子工程编译.md"}'),o={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子工程编译.md"};function e(i,t,u,c,g,q){return a(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="算子工程编译" tabindex="-1">算子工程编译 <a class="header-anchor" href="#算子工程编译" aria-label="Permalink to &quot;算子工程编译&quot;">​</a></h1><p>算子kernel侧和host侧实现开发完成后，需要对算子工程进行编译，生成自定义算子安装包*.run，详细的编译操作包括：</p><ul><li><p>编译Ascend C算子kernel侧代码实现文件*.cpp，分为源码发布和二进制发布两种方式。</p><ul><li><strong>源码发布</strong>：不对算子kernel侧实现进行编译，保留算子kernel源码文件*.cpp。该方式可以支持算子的在线编译、通过ATC模型转换的方式编译算子的场景。</li><li><strong>二进制发布</strong>：对算子kernel侧实现进行编译，生成描述算子相关信息的json文件*.json和算子二进制文件*.o。算子调用时，如果需要直接调用算子二进制，则使用该编译方式，比如通过<a href="./../单算子API调用.html">单算子API调用</a>的方式完成单算子的调用，PyTorch框架中单算子调用的场景，动态网络中调用算子的场景。</li></ul></li><li><p>编译Ascend C算子host侧代码实现文件*.cpp、*.h。</p><ul><li>将原型定义和shape推导实现编译成算子原型定义动态库libcust_opsproto_*.so，并生成算子原型对外接口op_proto.h。</li><li>将Tiling实现编译成Tiling动态库liboptiling.so等。</li><li>基于算子原型定义，自动生成单算子API调用代码和头文件aclnn_*.h，并编译生成单算子API调用的动态库libcust_opapi.so。</li></ul></li></ul><p>上述编译过程示意图如下：</p><p><strong>图 1</strong> 算子工程编译示意图<br><img src="'+p+`" alt="" title="算子工程编译示意图"></p><h2 id="编译步骤" tabindex="-1">编译步骤 <a class="header-anchor" href="#编译步骤" aria-label="Permalink to &quot;编译步骤&quot;">​</a></h2><ol><li><p>完成工程编译相关配置。</p><ul><li><p>修改工程目录下的CMakePresets.json cacheVariables的配置项。<strong>CMakePresets.json</strong>文件内容如下，需要配置的参数请参考<a href="#table2023245818513">表1</a>，其他参数会在工程创建时自动生成。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;version&quot;: 1,</span></span>
<span class="line"><span>    &quot;cmakeMinimumRequired&quot;: {</span></span>
<span class="line"><span>        &quot;major&quot;: 3,</span></span>
<span class="line"><span>        &quot;minor&quot;: 19,</span></span>
<span class="line"><span>        &quot;patch&quot;: 0</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;configurePresets&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;name&quot;: &quot;default&quot;,</span></span>
<span class="line"><span>            &quot;displayName&quot;: &quot;Default Config&quot;,</span></span>
<span class="line"><span>            &quot;description&quot;: &quot;Default build using Unix Makefiles generator&quot;,</span></span>
<span class="line"><span>            &quot;generator&quot;: &quot;Unix Makefiles&quot;,</span></span>
<span class="line"><span>            &quot;binaryDir&quot;: &quot;\${sourceDir}/build_out&quot;,</span></span>
<span class="line"><span>            &quot;cacheVariables&quot;: {</span></span>
<span class="line"><span>                &quot;CMAKE_BUILD_TYPE&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;Release&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ENABLE_SOURCE_PACKAGE&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;True&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ENABLE_BINARY_PACKAGE&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;True&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ASCEND_COMPUTE_UNIT&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;ascendxxx&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ENABLE_TEST&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;True&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;vendor_name&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;customize&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ASCEND_PYTHON_EXECUTABLE&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;STRING&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;python3&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;CMAKE_INSTALL_PREFIX&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;PATH&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;\${sourceDir}/build_out&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ENABLE_CROSS_COMPILE&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;False&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;CMAKE_CROSS_PLATFORM_COMPILER&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;PATH&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;/usr/bin/aarch64-linux-gnu-g++&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;ASCEND_PACK_SHARED_LIBRARY&quot;: {</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>                    &quot;value&quot;: &quot;False&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 1</strong> 需要开发者配置的参数列表</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;参数名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;参数描述&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;默认值&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;CMAKE_BUILD_TYPE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;编译模式选项，可配置为：&lt;/p&gt; &lt;ul&gt;&lt;li&gt;“Release”，Release版本，不包含调试信息，编译最终发布的版本。&lt;/li&gt;&lt;li&gt;“Debug”，“Debug”版本，包含调试信息，便于开发者开发和调试。&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“Release”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;ENABLE_SOURCE_PACKAGE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;是否开启源码编译&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“True”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;ENABLE_BINARY_PACKAGE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;是否开启二进制编译&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“True”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;vendor_name&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;标识自定义算子所属厂商的名称。建议开发者自行指定所属厂商名称，避免和其他厂商提供的算子包冲突。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“customize”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.63%&quot;&gt;&lt;p&gt;ASCEND_PACK_SHARED_LIBRARY&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.47%&quot;&gt;&lt;p&gt;是否开启&lt;a href=&quot;../算子动态库和静态库编译.md&quot;&gt;动态库编译功能。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“False”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>配置编译相关环境变量（可选）</p><p><strong>表 2</strong> 环境变量说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.54%&quot;&gt;&lt;p&gt;环境变量&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;70.46%&quot;&gt;&lt;p&gt;配置说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.54%&quot;&gt;&lt;p&gt;CMAKE_CXX_COMPILER_LAUNCHER&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;70.46%&quot;&gt;&lt;p&gt;用于配置C++语言编译器（如g++）、毕昇编译器的启动器程序为ccache，配置后即可开启cache缓存编译，&lt;span&gt;加速重复编译并提高构建效率&lt;/span&gt;。使用该功能前需要安装ccache。&lt;/p&gt; &lt;p&gt;配置方法如下，在对应的CMakeLists.txt进行设置：&lt;/p&gt; &lt;pre class=&quot;screen&quot;&gt;set(CMAKE_CXX_COMPILER_LAUNCHER &lt;launcher_program&gt;)&lt;/pre&gt; &lt;p&gt;其中&lt;launcher_program&gt;是ccache的安装路径，比如ccache的安装路径为/usr/bin/ccache，示例如下：&lt;/p&gt; &lt;pre class=&quot;screen&quot;&gt;set(CMAKE_CXX_COMPILER_LAUNCHER /usr/bin/ccache)&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul></li><li><p>在算子工程目录下执行如下命令，进行算子工程编译。</p><p><strong>./build.sh</strong></p><p>编译成功后，会在当前目录下创建build_out目录，并在build_out目录下生成自定义算子安装包custom_opp_&lt;target os&gt;__&lt;target architecture&gt;.run。</p><p>用户如果需要编译过程日志存盘，可以使用环境变量ASCENDC_BUILD_LOG_DIR来控制存储路径。用户设置该选项之后，如果编译过程中无错误产生，则对应的log文件后缀会添加&quot;_success&quot;，若编译过程有错误产生，则会在屏幕打印对应的报错信息，以及指示用户log文件的具体路径与文件名，同时，对应log文件后缀会添加“_error”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 如希望编译日志存储在/home/build_log/，则可以按照如下设置，默认不打开日志存储</span></span>
<span class="line"><span>export ASCENDC_BUILD_LOG_DIR=/home/build_log/</span></span></code></pre></div></li></ol><h2 id="算子包交叉编译" tabindex="-1">算子包交叉编译 <a class="header-anchor" href="#算子包交叉编译" aria-label="Permalink to &quot;算子包交叉编译&quot;">​</a></h2><p>完成算子代码实现后，如果当前平台架构和运行环境一致则参考上一节的内容进行编译即可，如果需要实现算子包的交叉编译，您可以参考如下流程。</p><ol><li><p>交叉编译工具下载，下表以Ubuntu系列操作系统为例，展示了编译工具下载命令的样例。其他操作系统，请替换为实际的下载命令。</p><p><strong>表 3</strong> Ubuntu系列操作系统交叉编译工具下载命令样例</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.21192119211921%&quot;&gt;&lt;p&gt;当前平台架构&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;26.192619261926193%&quot;&gt;&lt;p&gt;运行环境平台架构&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.595459545954604%&quot;&gt;&lt;p&gt;编译工具下载命令&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.21192119211921%&quot;&gt;&lt;p&gt;x86_64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;26.192619261926193%&quot;&gt;&lt;p&gt;aarch64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.595459545954604%&quot;&gt;&lt;p&gt;sudo apt-get install -y g++-aarch64-linux-gnu&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.21192119211921%&quot;&gt;&lt;p&gt;aarch64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;26.192619261926193%&quot;&gt;&lt;p&gt;x86_64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.595459545954604%&quot;&gt;&lt;p&gt;sudo apt-get install g++-x86-64-linux-gnu&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>自定义算子工程交叉编译，构建生成自定义算子包。</p><ol><li><p>修改CMakePresets.json中ENABLE_CROSS_COMPILE为True，使能交叉编译。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ENABLE_CROSS_COMPILE&quot;: {</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>    &quot;value&quot;: &quot;True&quot;</span></span>
<span class="line"><span> }</span></span></code></pre></div></li><li><p>修改CMakePresets.json中CMAKE_CROSS_PLATFORM_COMPILER为安装后的交叉编译工具路径。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;CMAKE_CROSS_PLATFORM_COMPILER&quot;: {</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;PATH&quot;,</span></span>
<span class="line"><span>    &quot;value&quot;: &quot;/usr/bin/aarch64-linux-gnu-g++&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>在算子工程目录下执行如下命令，进行算子工程交叉编译。</p><p><strong>./build.sh</strong></p><p>编译成功后，会在当前目录下创建build_out目录，并在build_out目录下生成自定义算子安装包custom_opp_&lt;target os&gt;__&lt;target architecture&gt;.run</p></li></ol></li></ol><h2 id="支持自定义编译选项" tabindex="-1">支持自定义编译选项 <a class="header-anchor" href="#支持自定义编译选项" aria-label="Permalink to &quot;支持自定义编译选项&quot;">​</a></h2><p>在算子工程中，如果开发者想对算子kernel侧代码增加一些自定义的编译选项，可以参考如下内容进行编译选项的定制。</p><p>修改算子工程op_kernel目录下的CMakeLists.txt，使用add_ops_compile_options来增加编译选项，方法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ops_compile_options(OpType COMPUTE_UNIT soc_version1 soc_version2 ... OPTIONS option1 option2 ...)</span></span></code></pre></div><p>具体参数的介绍如下：</p><p><strong>表 4</strong> 具体参数介绍</p><table tabindex="0"><thead><tr><th>参数名称</th><th>可选/必选</th><th>参数描述</th></tr></thead><tbody><tr><td>OpType（算子类型）</td><td>必选</td><td>第一个参数应传入算子类型，如果需要对算子工程中的所有算子生效，需要配置为ALL。</td></tr><tr><td>COMPUTE_UNIT</td><td>可选</td><td>标识编译选项在哪些AI处理器型号上生效，多个型号之间通过空格间隔。不配置时表示对所有AI处理器型号生效。</td></tr><tr><td>OPTIONS</td><td>必选</td><td>自定义的编译选项。多个编译选项之间通过空格间隔。&lt;br/&gt;&lt;ul&gt;&lt;li&gt;增加-D编译选项，用于在编译时定义宏。&lt;pre class=&quot;screen&quot;&gt;OPTIONS -Dname=definition&lt;/pre&gt;&lt;/li&gt;&lt;li&gt;增加-g -O0等调试用编译选项。&lt;/li&gt;&lt;li&gt;支持传入毕昇编译器编译选项：比如--cce-auto-sync=off，设置该选项可以关闭自动同步功能，自定义算子工程已默认开启，通常无需开发者手动设置。详细内容参见<a href="https://www.hiascend.com/document/redirect/CannCommunityBiSheng" target="_blank" rel="noreferrer">《毕昇编译器用户指南》</a>。&lt;/li&gt;&lt;li&gt;Ascend C框架提供的编译选项，具体内容参考下文详细介绍。&lt;/li&gt;&lt;/ul&gt;</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>COMPUTE_UNIT的获取方式如下：</p><ul><li>针对如下产品：在安装AI处理器的服务器执行npu-smi info命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。&lt;br/&gt;&lt;br/&gt; Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> Atlas 200I/500 A2 推理产品<br> Atlas 推理系列产品<br> Atlas 训练系列产品&lt;br/&gt;&lt;br/&gt;</li><li>针对&lt;term&gt;Atlas A3 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A3 推理系列产品&lt;/term&gt;，在安装AI处理器的服务器执行npu-smi info -t board -i id -c chip_id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：&lt;br/&gt;id：设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。&lt;br/&gt; chip_id：芯片id，通过npu-smi info -m命令查出的Chip ID即为芯片id。&lt;br/&gt;&lt;br/&gt;</li><li>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行npu-smi info -t board -i id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。&lt;br/&gt; 其中：id为设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。</li></ul></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>编译选项是基于“算子类型+AI处理器型号系列”进行配置的，也就是说不同的“算子类型+AI处理器型号系列”可以配置不同的编译选项。<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ops_compile_options(AddCustom COMPUTE_UNIT Ascendxxxyy ... OPTIONS -DNEW_MACRO1=xx)</span></span>
<span class="line"><span>add_ops_compile_options(AddCustom COMPUTE_UNIT Ascendxxxyy ... OPTIONS -DNEW_MACRO2=xx)</span></span>
<span class="line"><span>add_ops_compile_options(AddCustom COMPUTE_UNIT Ascendxxxyy ... OPTIONS -DNEW_MACRO3=xx)</span></span></code></pre></div></li><li>对相同算子类型+AI处理器型号系列，做多次编译选项配置，以后配置的为准。</li><li>对ALL生效的编译选项和对单一算子生效的编译选项如果没有冲突，同时生效，如果有冲突，以单一算子的编译选项为准。</li></ul></div><p>Ascend C框架提供的编译选项介绍如下：</p><ul><li><p>--tiling_key，设置该选项后，只编译指定的<a href="./../Host侧Tiling实现/基本流程.html">TilingKey</a>相关的kernel代码，用于加速编译过程。若不指定TilingKey编译，则默认编译所有的TilingKey。配置多个TilingKey时，TilingKey之间不能有空格。示例如下，其中1、2为tiling_key。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--tiling_key=1,2</span></span></code></pre></div></li><li><p>编译宏开关请参考<a href="./../../../../编译与运行/AI-Core-SIMD编译/常用的编译选项.html">内置编译宏开关</a>。</p></li><li><p>--op_relocatable_kernel_binary，设置该选项为true时，会额外编译一份可被重新链接的二进制文件；不配置或设置为false时该选项均不生效。该选项用于自定义Tiling下沉算子使能SuperKernel的场景，配置该选项所生成的二进制文件，可以使算子在SuperKernel编译时直接复用二进制文件，降低编译耗时。</p></li><li><p>--kernel-template-input，用于<a href="./../Host侧Tiling实现/Tiling模板编程.html">算子工程模板编程</a>，设置该选项后，只编译指定的模板参数组合相关的Kernel代码，用于加速编译过程。若不设置该选项，则默认编译所有的模板参数组合。传入的参数为键值对列表，整体需用双引号或单引号包裹。不同模板参数之间用英文分号（;）分隔，相同模板参数配置多个值时用英文逗号（,）分隔。配置时不能有空格。示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--kernel-template-input=&quot;D_T_X=A1,A2;D_T_Y=B;D_T_Z=C&quot;</span></span>
<span class="line"><span>--kernel-template-input=&#39;D_T_X=A1,A2;D_T_Y=B;D_T_Z=C&#39;</span></span></code></pre></div><p>配置模板参数组合时，模板参数名需要与Kernel入口处以及Host侧定义的模板参数名匹配。对于模板参数组合的值，如果存在自定义类型，需要替换为其对应数字值，如果为原生支持数据类型，则与Kernel入口处入参保持一致。示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Host侧模板参数定义</span></span>
<span class="line"><span>#define ADD_TPL_FP16 10</span></span>
<span class="line"><span>#define ADD_TPL_FP32 20</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ASCENDC_TPL_ARGS_DECL(AddCustomTemplateNativeDtype,</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_DECL(D_T_X, C_DT_FLOAT, C_DT_FLOAT16, ASCENDC_TPL_INPUT(0)),</span></span>
<span class="line"><span>    ASCENDC_TPL_DTYPE_DECL(D_T_Y, ADD_TPL_FP16, ADD_TPL_FP32),</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_DECL(D_T_Z, C_DT_FLOAT, C_DT_FLOAT16, ASCENDC_TPL_OUTPUT(0)),</span></span>
<span class="line"><span>    ASCENDC_TPL_UINT_DECL(TILE_NUM, ASCENDC_TPL_8_BW, ASCENDC_TPL_UI_MIX, 2, 0, 2, 3, 5, 10, 12, 13, 9, 8),</span></span>
<span class="line"><span>    ASCENDC_TPL_BOOL_DECL(IS_SPLIT, 0, 1),</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ASCENDC_TPL_SEL(</span></span>
<span class="line"><span>    ASCENDC_TPL_ARGS_SEL(</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_SEL(D_T_X, C_DT_FLOAT),</span></span>
<span class="line"><span>    ASCENDC_TPL_DTYPE_SEL(D_T_Y, ADD_TPL_FP32),</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_SEL(D_T_Z, C_DT_FLOAT),</span></span>
<span class="line"><span>    ASCENDC_TPL_UINT_SEL(TILE_NUM, ASCENDC_TPL_UI_LIST, 1, 8),</span></span>
<span class="line"><span>    ASCENDC_TPL_BOOL_SEL(IS_SPLIT, 0, 1),</span></span>
<span class="line"><span>    ASCENDC_TPL_DETERMINISTIC_SEL(true),</span></span>
<span class="line"><span>    ASCENDC_TPL_KERNEL_TYPE_SEL(ASCENDC_TPL_AIV_ONLY),</span></span>
<span class="line"><span>    ),</span></span>
<span class="line"><span>    ASCENDC_TPL_ARGS_SEL(</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_SEL(D_T_X, C_DT_FLOAT16),</span></span>
<span class="line"><span>    ASCENDC_TPL_DTYPE_SEL(D_T_Y, ADD_TPL_FP16),</span></span>
<span class="line"><span>    ASCENDC_TPL_DATATYPE_SEL(D_T_Z, C_DT_FLOAT16),</span></span>
<span class="line"><span>    ASCENDC_TPL_UINT_SEL(TILE_NUM, ASCENDC_TPL_UI_LIST, 1, 8),</span></span>
<span class="line"><span>    ASCENDC_TPL_BOOL_SEL(IS_SPLIT, 0, 1),</span></span>
<span class="line"><span>    ASCENDC_TPL_DETERMINISTIC_SEL(false),</span></span>
<span class="line"><span>    ASCENDC_TPL_KERNEL_TYPE_SEL(ASCENDC_TPL_AIV_ONLY),</span></span>
<span class="line"><span>    ),</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//kernel入口</span></span>
<span class="line"><span>if constexpr (std::is_same_v&lt;D_T_X, float&gt; &amp;&amp; std::is_same_v&lt;D_T_Z, float&gt;) {</span></span>
<span class="line"><span>        KernelAdd&lt;D_T_X, float, D_T_Z&gt; op;</span></span>
<span class="line"><span>        op.Init(x, y, z, tiling_data.totalLength, TILE_NUM);</span></span>
<span class="line"><span>        op.Process1();</span></span>
<span class="line"><span>    } else if constexpr (std::is_same_v&lt;D_T_X, half&gt; &amp;&amp; std::is_same_v&lt;D_T_Z, half&gt;){</span></span>
<span class="line"><span>        KernelAdd&lt;D_T_X, half, D_T_Z&gt; op;</span></span>
<span class="line"><span>        op.Init(x, y, z, tiling_data.totalLength, TILE_NUM);</span></span></code></pre></div><p>编译选项示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--kernel-template-input=&quot;D_T_X=10;D_T_Y=half;D_T_Z=10&quot; </span></span>
<span class="line"><span>--kernel-template-input=&quot;D_T_X=10,20;D_T_Y=half,float;D_T_Z=10,20&quot;</span></span></code></pre></div></li></ul>`,21)])])}const _=s(o,[["render",e]]);export{d as __pageData,_ as default};
